static void Epaper_Load_Image_S2(uint8_t *image)
{
	unsigned long i;
	uint8_t colordata, colordata1, colordata2, colordata3, colordata4, temp, a = 0, b = 0, c = 0, d = 0;

	EPD_W21_WriteCMD_S2(0x10);
	{
		//    for(i=0;i<492*648/4;i++)
		for (i = 492 * 648 / 4; i > 0; i--)
		//    for(i=0;i<3;i++)
		{
			temp = image[i - 1];
			//			temp=0x69;
			a = temp & 0xc0;
			a = a >> 6;
			b = temp & 0x30;
			b = b >> 2;
			c = temp & 0x0c;
			c = c << 2;
			d = temp & 0x03;
			d = d << 6;
			temp = a | b | c | d;
			//							printf("0x%02x\r\n",(uint8_t)temp);

			if ((temp & 0x40) == 0x40) {
				if ((temp & 0x80) == 0x80)
					colordata1 = 0x40;
				else
					colordata1 = 0xc0;

			} else
				colordata1 = temp & 0xc0;
			//					printf("0x%02x\r\n",(uint8_t)colordata1);

			if ((temp & 0x10) == 0x10) {
				if ((temp & 0x20) == 0x20)
					colordata2 = 0x10;
				else
					colordata2 = 0x30;

			} else
				colordata2 = temp & 0x30;
			//					printf("0x%02x\r\n",(uint8_t)colordata2);

			if ((temp & 0x04) == 0x04) {
				if ((temp & 0x08) == 0x08)
					colordata3 = 0x04;
				else
					colordata3 = 0x0c;

			} else
				colordata3 = temp & 0x0c;
			//					printf("0x%02x\r\n",(uint8_t)colordata3);

			if ((temp & 0x01) == 0x01) {
				if ((temp & 0x02) == 0x02)
					colordata4 = 0x01;
				else
					colordata4 = 0x03;

			} else
				colordata4 = temp & 0x03;
			//					printf("0x%02x\r\n",(uint8_t)colordata4);

			colordata = colordata1 | colordata2 | colordata3 | colordata4;

			//				printf("0x%02x\r\n",(uint8_t)colordata);
			//				printf("\r\n");
			EPD_W21_WriteDATA_S2(colordata);
			//			image++;

			//			Epaper_Write_Data(*image++);
		}
	}
}

